INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 1, 'theory', 'Квиз: SSH, tmux и sudo');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 1, 0, 'В sshd_config выше стоит «PasswordAuthentication no», а ниже блок «Match User backup» со строкой «PasswordAuthentication yes». Сможет ли backup войти по паролю?', '["Да, Match всегда сильнее общих строк", "Да, потому что побеждает последнее значение", "Нет, побеждает первое найденное значение", "Нет, внутри Match этот параметр запрещён"]', 2, 'В sshd_config для большинства параметров действует первое найденное значение. Строка до Match уже задала no, поэтому yes в блоке игнорируется. Чтобы разрешить пароль одному пользователю, нужно поставить Match выше общей строки.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 1, 1, 'При подключении ssh пишет, что хост-ключ известного сервера изменился. Что правильно сделать первым?', '["Выяснить по другому каналу, переустанавливали ли сервер и каков его отпечаток", "Удалить файл known_hosts и подключиться заново", "Поставить StrictHostKeyChecking no в конфиге", "Сменить свой ключ на новый"]', 0, 'Смена ключа бывает после переустановки, но может означать и подмену сервера. Сверьте отпечаток по независимому каналу и только потом удаляйте старую запись командой ssh-keygen -R.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 1, 2, 'Какая строка authorized_keys пускает ключ только из сети 10.0.0.0/8 и запрещает ему проброс портов и терминал?', '["allow=\"10.0.0.0/8\",restrict ssh-ed25519 AAAA...", "from=10.0.0.0/8 ssh-ed25519 AAAA... no-pty", "restrict ssh-ed25519 AAAA... from=\"10.0.0.0/8\"", "from=\"10.0.0.0/8\",restrict ssh-ed25519 AAAA..."]', 3, 'Опции стоят перед типом ключа, разделяются запятыми без пробелов, значение from берётся в кавычки. Restrict отключает проброс и терминал сразу. Опции после ключа считаются комментарием.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 1, 3, 'Вы меняете sshd_config на удалённом сервере. Какой порядок действий безопасный?', '["Правка, restart, затем проверка входа", "Вторая сессия, правка, sshd -t, reload, проверка новым входом", "Правка, закрыть все сессии, restart службы", "Правка и sshd -t, но без reload до перезагрузки сервера"]', 1, 'Открытая вторая сессия остаётся рабочей при reload, и через неё можно откатить ошибку. Проверка sshd -t ловит синтаксис, а новый вход подтверждает, что логика настроек не заперла вас.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 1, 4, 'В sudoers сначала идёт «%sudo ALL=(ALL:ALL) ALL», ниже «ann ALL=(ALL) NOPASSWD: /usr/bin/apt». Ann состоит в группе sudo и запускает apt. Что произойдёт?', '["sudo спросит пароль, потому что группа точнее", "sudo откажет из-за конфликта двух правил", "sudo не спросит пароль для apt, а для остальных команд спросит", "sudo не спросит пароль ни для каких команд"]', 2, 'Последняя подошедшая запись выигрывает. Для apt это правило ann с NOPASSWD, поэтому пароль не нужен. Для остальных команд подходит только правило группы, и пароль нужен.');
